
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar':'Menú';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú';menu.focus()}});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));

const intelligenceStages=[{"name": "Brief y contexto", "input": "El brief, las restricciones y las fuentes disponibles.", "work": "Investigamos mercado, competencia, consumidor y entorno con apoyo de IA y revisión experta.", "output": "Un contexto estratégico que orienta las preguntas del proyecto.", "review": "Si cambia una premisa del negocio, revisamos los objetivos y el alcance."}, {"name": "Objetivos de investigación", "input": "El contexto comprendido y la decisión que necesita apoyar el cliente.", "work": "Traducimos el reto en objetivos, preguntas clave y un plan de investigación.", "output": "Objetivos acordados que dan propósito a cada análisis.", "review": "Contrastamos nuevas preguntas con la necesidad original para mantener el enfoque."}, {"name": "Arquitectura analítica", "input": "Los objetivos y las respuestas que necesitamos obtener.", "work": "Diseñamos módulos, modelos y variables antes de construir el instrumento.", "output": "Una ruta: pregunta de negocio → respuesta esperada → análisis → información necesaria.", "review": "Si falta una variable o un análisis no responde al objetivo, ajustamos el diseño."}, {"name": "Muestra y cuestionario", "input": "La arquitectura analítica y la población que queremos comprender.", "work": "Diseñamos o apoyamos muestra, cuestionario y validación del instrumento. Acordamos quién realiza el levantamiento.", "output": "Un instrumento alineado con los análisis y un plan de obtención de información.", "review": "El pretest y la viabilidad del campo pueden requerir revisar preguntas y cobertura."}, {"name": "Validación y calidad de datos", "input": "La base obtenida y el cuestionario, o las fuentes acordadas para el proyecto.", "work": "Relacionamos variables y estructura; aplicamos controles y revisamos anomalías y faltantes.", "output": "Una base revisada y límites documentados para la ejecución.", "review": "Una inconsistencia puede exigir corregir datos o acotar un análisis, no ocultar el problema."}, {"name": "Ejecución analítica", "input": "La base revisada, la arquitectura y los criterios del proyecto.", "work": "Desarrollamos scripts y ejecutamos modelos y análisis; contrastamos consistencia y resultados.", "output": "Resultados reproducibles vinculados con las preguntas de negocio.", "review": "Los diagnósticos pueden requerir ajustar el modelo y revisar los supuestos."}, {"name": "Descubrimiento de insights", "input": "Los resultados del plan, el contexto y los hallazgos adicionales.", "work": "Integramos y contrastamos evidencia, exploramos patrones y priorizamos implicaciones.", "output": "Insights que explican qué significa el resultado y por qué importa.", "review": "Un hallazgo adicional se valida antes de incorporarlo a la historia o abrir otra pregunta."}, {"name": "Entrega ejecutiva", "input": "Los insights priorizados y la decisión original.", "work": "Construimos la narrativa, los soportes y las recomendaciones; desarrollamos herramientas según el alcance.", "output": "Una presentación, reporte o herramienta con contexto, evidencia y límites.", "review": "Las preguntas del equipo retroalimentan la interpretación; el seguimiento se acuerda con el cliente."}];
const applications=[{"title": "Oferta y precios en moda", "question": "Evaluar ofertas, precios y promociones en moda.", "status": "INVESTIGACIÓN APLICADA + HERRAMIENTA DE CONSULTA", "intro": "En una investigación de moda, conectamos la evaluación de prendas, precios y promociones con una herramienta para explorar escenarios. El trabajo permitió estudiar la elección entre ofertas y poner los resultados al alcance del equipo mediante una presentación ejecutiva y un simulador/reporteador.", "anchor": "¿Cómo se relacionan producto, precio y promoción con la preferencia?", "limit": "Alcance: evaluación de preferencias y escenarios bajo las condiciones del estudio. No equivale a pronosticar ventas. La muestra pública omite marcas, cifras y resultados del cliente.", "steps": ["Leímos el brief y ampliamos el contexto de la categoría: alternativas de oferta, referencias de mercado y condiciones relevantes para la decisión. Esto evitó tratar el análisis como una comparación de precios aislada.", "Convertimos el reto en preguntas concretas sobre elección de prendas, sensibilidad al precio y promociones. Acordamos qué necesitaba conocer el equipo y qué quedaba fuera del alcance.", "Organizamos cada pregunta en un módulo analítico y definimos las variables y ejercicios necesarios. Así, las respuestas esperadas orientaron el cuestionario y las alternativas que se evaluarían.", "Conectamos los módulos elegidos con el cuestionario y los ejercicios de evaluación. En este proyecto, el cliente hizo el levantamiento; el servicio de Go-Ideas también puede incluirlo en otros alcances.", "Contrastamos la base recibida con el cuestionario y el diseño de los ejercicios. Revisamos que la información pudiera sostener las comparaciones antes de producir e interpretar resultados.", "Analizamos las elecciones y los módulos de precio y promoción acordados. La lectura distingue la preferencia estimada bajo las condiciones del estudio de una predicción de compra real.", "Integramos los módulos para explicar qué diferencias merecían atención y qué alternativas convenía discutir. Los resultados se interpretaron con el contexto del proyecto, no como rankings desconectados.", "Construimos una presentación ejecutiva y un simulador/reporteador con filtros y guía. La herramienta permite consultar y comparar los escenarios previstos; la presentación aporta la interpretación y los límites."], "built": "Diseñamos los ejercicios de evaluación y desarrollamos los análisis para interpretar las elecciones. Después construimos un simulador/reporteador con filtros: el equipo podía consultar resultados y explorar las combinaciones previstas en el estudio, sin depender únicamente de una presentación estática.", "method": "Partimos del brief y del contexto de la categoría. Tradujimos los objetivos en módulos y variables antes de apoyar el cuestionario; el cliente realizó el levantamiento. Con la base recibida, revisamos su estructura, ejecutamos los análisis y conectamos los hallazgos con la pregunta comercial.", "delivered": "Una presentación que explica los hallazgos y sus implicaciones, archivos de soporte y una herramienta de consulta con guía de uso. La entrega permite relacionar cada lectura con su evidencia y entender bajo qué condiciones se construyeron los escenarios.", "need": "El reto era entender cómo se relacionan las características de una prenda, su precio y su promoción con la elección. Para marketing, la pregunta va más allá de qué opción gusta: interesa comparar propuestas y reconocer qué información hace falta antes de modificar una oferta.", "questions": "¿Qué características pesan en la elección? ¿Cómo cambia la preferencia entre alternativas de producto, precio y promoción? ¿Qué diferencias aparecen entre los perfiles disponibles en el estudio?", "use": "Un equipo de marketing puede utilizar esta lectura para preparar una discusión de portafolio, contrastar propuestas de valor y decidir qué alternativas pasar a una siguiente prueba. Son usos posibles del entregable; no afirmamos que el estudio haya producido un aumento de ventas."}, {"title": "Text Analytics y desarrollo", "question": "Escuchar al mercado y convertir sus palabras en una lectura útil.", "status": "ANÁLISIS DE TEXTO + SOFTWARE PROPIO", "intro": "En trabajos de respuestas abiertas, organizamos y analizamos lo que las personas expresan para relacionar temas, percepciones y diferencias entre perfiles. Esta experiencia se complementa con un motor propio de clasificación que puede asistir el trabajo, con revisión humana.", "anchor": "¿Qué expresan las personas, cómo se relacionan los temas y qué implica para el negocio?", "limit": "Alcance: clasificación y análisis interpretativo con revisión humana. La frecuencia de un tema no demuestra su importancia comercial; el motor no se atribuye a todos los estudios.", "steps": ["Partimos del brief para entender qué necesita conocer el negocio y qué papel tienen las opiniones de las personas. El contexto orienta la lectura y evita confundir una palabra frecuente con un hallazgo relevante.", "Se definen las preguntas que guiarán la lectura de opiniones y su relación con otras medidas del estudio.", "Definimos cómo organizar y comparar temas, asociaciones y perfiles, y qué información adicional ayudará a interpretar. El diseño conecta el análisis textual con los objetivos del estudio.", "Se apoyan preguntas abiertas e instrumentos que permitan responder a los objetivos, según el diseño y las fuentes del proyecto.", "Se revisan estructura, cobertura y textos disponibles antes de su integración analítica.", "Preparamos, codificamos y analizamos las respuestas para identificar patrones y asociaciones. Las herramientas propias pueden asistir la clasificación; la revisión humana verifica significado, ambigüedades y coherencia.", "Relacionamos temas con el contexto y con los resultados cuantitativos disponibles. Diferenciamos evidencia, interpretación e hipótesis antes de formular implicaciones para comunicación o marketing.", "Entregamos bases, soportes visuales y una presentación que explica qué expresan las personas, cómo se comparan los perfiles y qué preguntas conviene explorar después."], "built": "Desarrollamos análisis de texto y una capacidad propia para apoyar la clasificación de respuestas. El trabajo reúne preparación de información, organización temática, revisión de ambigüedades y salidas analizables. El motor se incorpora según el alcance; no atribuimos su uso a todos los estudios.", "method": "El brief define qué necesitamos comprender y qué fuentes son pertinentes. Acordamos criterios de análisis, revisamos las respuestas y contrastamos temas con otras medidas del estudio. La IA puede asistir tareas de clasificación; el equipo revisa los casos y construye la interpretación.", "delivered": "Bases codificadas, tablas y visualizaciones para explorar temas y perfiles, además de una presentación que integra el significado de los hallazgos. Los resultados conservan soporte para revisar las lecturas y discutir sus límites.", "need": "Los comentarios contienen matices que una tabla cerrada no explica, pero leerlos uno por uno dificulta comparar patrones y conservar una visión de conjunto. El reto consiste en dar estructura a esa información sin perder el significado de las respuestas.", "questions": "¿Qué temas aparecen y cómo se relacionan? ¿Qué diferencias hay entre públicos o percepciones de marca? ¿Qué expresiones ayudan a entender los resultados cuantitativos y qué interpretaciones necesitan más evidencia?", "use": "Marketing y comunicación pueden utilizar esta lectura para revisar lenguaje, contrastar percepciones, preparar hipótesis de mensajes o profundizar en tensiones de la experiencia. Encontrar un tema frecuente no demuestra que un mensaje vaya a funcionar: requiere evaluación adicional."}, {"title": "Auditoría visual de publicidad", "question": "Software propio para auditar evidencia visual en publicidad.", "status": "DESARROLLO PROPIO · APLICACIÓN EN MOVILIDAD", "intro": "Desarrollamos software para organizar y auditar videos de pasajeros frente a una pantalla publicitaria. La herramienta preclasifica evidencia de orientación visual y genera indicadores que pueden contrastarse con fotografías del material de origen. El propósito es hacer la revisión más estructurada y trazable.", "anchor": "¿Qué evidencia visual puede revisarse para estudiar la orientación hacia la publicidad?", "limit": "Alcance: conducta visual observable. No mide atención cognitiva ni equivale a eye tracking. Los resultados dependen de las condiciones de captura y validación; no se declara una precisión nueva en esta muestra.", "steps": ["Precisamos el contexto de exposición y la pregunta que la revisión de videos debía ayudar a responder.", "Acordamos un objetivo observable: revisar señales de orientación hacia la pantalla y la proporción de evidencia evaluable. Mantuvimos separado ese objetivo de comprensión, recuerdo y eficacia del anuncio.", "Conectamos los criterios de observación, la información requerida y las salidas necesarias para una auditoría revisable.", "Adaptamos el diseño a las condiciones de video y a la evidencia disponible, sin imponer un instrumento de encuesta.", "Revisamos si las imágenes permiten evaluar la conducta visual. Los periodos oscuros, borrosos u obstruidos no se interpretan automáticamente como falta de orientación; se conserva su condición de evidencia insuficiente.", "El software combina análisis automatizado y revisión humana para preclasificar evidencia y generar métricas.", "Leemos los indicadores junto con la calidad, cobertura y fuente de clasificación. Una proporción positiva debe interpretarse considerando cuánto material pudo auditarse; la señal visual no demuestra atención cognitiva.", "Entregamos reportes con métricas y fotografías de soporte. La revisión permite volver a la evidencia y discutir comparaciones dentro de las condiciones observadas, sin atribuir resultados de eficacia publicitaria."], "outputs": ["Una pregunta situada en su contexto de exposición.", "Un objetivo observable y un alcance explícito.", "Criterios de análisis conectados con los entregables.", "Condiciones de observación adaptadas al material.", "Evidencia evaluable y límites de cobertura identificados.", "Métricas y preclasificaciones sujetas a revisión.", "Una interpretación contextualizada y acotada.", "Reportes revisables con evidencia y límites de uso."], "built": "Un software propio que organiza el material, asiste su revisión y genera preclasificaciones y métricas. Combina programación, análisis automatizado y auditoría humana para que cada lectura pueda revisarse contra las imágenes que la sustentan. El equipo mantiene control sobre la revisión e interpretación.", "method": "El ecosistema conecta la pregunta publicitaria con los criterios de observación, la calidad del material y los indicadores de entrega. El software ayuda a clasificar la evidencia y los auditores la revisan. Una imagen sin condiciones suficientes se distingue de una respuesta negativa; esa diferencia importa al interpretar los porcentajes.", "delivered": "Reportes con tiempos y porcentajes por video, formato y categoría, acompañados de evidencia fotográfica. La entrega distingue la fuente automática de la revisión humana y declara la cobertura temporal utilizada, para que los indicadores se lean en su contexto.", "need": "Para revisar exposición publicitaria en movilidad, no basta con comprobar que una persona aparece frente a una cámara. El reto es distinguir evidencia de orientación hacia la pantalla de material que no permite evaluarla, y resumir esa observación sin perder su soporte visual.", "questions": "¿Qué intervalos contienen señales observables de orientación hacia la pantalla? ¿Qué proporción del material puede evaluarse? ¿Cómo cambian los indicadores entre videos, formatos y categorías, considerando sus condiciones de captura?", "use": "Publicidad y comunicación pueden utilizar los reportes para comparar evidencia observable entre los materiales evaluados, detectar limitaciones de captura y formular preguntas para una siguiente evaluación. No permiten concluir por sí solos que una pieza se comprendió, se recordó o generó una respuesta comercial."}];
let intelligenceStage=0,applicationStage=0,applicationIndex=0;
function renderIntelligence(){
 const item=intelligenceStages[intelligenceStage];
 document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.intelligenceStage)===intelligenceStage)));
 document.querySelector('[data-intelligence-number]').textContent='ETAPA '+String(intelligenceStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-intelligence-title]').textContent=item.name;
 document.querySelectorAll('[data-intelligence]').forEach(e=>{e.textContent=item[e.dataset.intelligence]});
}
function renderApplication(){
 const item=applications[applicationIndex];
 document.querySelectorAll('[data-application]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.application)===applicationIndex)));
 document.querySelectorAll('[data-application-field]').forEach(e=>{e.textContent=item[e.dataset.applicationField]});
 document.querySelectorAll('[data-application-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.applicationStage)===applicationStage)));
 document.querySelector('[data-application-number]').textContent='ETAPA '+String(applicationStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-application-title]').textContent=intelligenceStages[applicationStage].name;
 document.querySelector('[data-application-text]').textContent=item.steps[applicationStage];
 document.querySelector('[data-application-return]').textContent=item.outputs ? item.outputs[applicationStage] : intelligenceStages[applicationStage].output;
}
document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.addEventListener('click',()=>{intelligenceStage=Number(b.dataset.intelligenceStage);renderIntelligence()}));
document.querySelectorAll('[data-application]').forEach(b=>b.addEventListener('click',()=>{applicationIndex=Number(b.dataset.application);renderApplication()}));
document.querySelectorAll('[data-application-stage]').forEach(b=>b.addEventListener('click',()=>{applicationStage=Number(b.dataset.applicationStage);renderApplication()}));
